if(reactionRows.some(r=>r.message_id===messageId&&r.reaction===reaction&&r.visitor_id===visitorId)){status(statusEl,"You have already reacted with "+reaction+".","");return}
if(button)button.disabled=true;
const {data,error}=await db.from("hub_chat_reactions").insert({message_id:messageId,room,visitor_id:visitorId,reaction}).select("id,message_id,room,visitor_id,reaction,created_at").maybeSingle();
