function currentPresenceRoster(){
if(!globalPresenceChannel)return [];
const states=globalPresenceChannel.presenceState(),people=[];
Object.entries(states).forEach(([key,entries])=>{
const list=Array.isArray(entries)?entries:[];
const latest=[...list].reverse().find(p=>p&&typeof p.room==="string");
if(!latest)return;
people.push({key,room:latest.room,nickname:String(latest.nickname||"Neighbor").trim().slice(0,32)||"Neighbor",member:latest.member===true,joined_at:latest.joined_at||""});
});
return people;
}
