try{
await globalPresenceChannel.track({room,nickname:activeChatName(),member:!!chatMember,joined_at:new Date().toISOString()});
updateRoomCounts();
}catch(e){connectionEl.textContent="Presence unavailable";onlineEl.textContent="—"}
