async function loadHeroVideo(){
 const hero=$(".hero");if(!hero||!db)return;
 try{const {data,error}=await db.from("hub_site_settings").select("video_url,poster_url,autoplay,loop_video").eq("setting_key","hero_video").maybeSingle();if(error||!data||!String(data.video_url||"").trim())return;
 const raw=String(data.video_url).trim();let u;try{u=new URL(raw)}catch(e){return}if(!["https:","http:"].includes(u.protocol))return;
 const layer=document.createElement("div");layer.className="hero-video-layer";
 const yt=u.hostname==="youtu.be"||u.hostname==="youtube.com"||u.hostname.endsWith(".youtube.com"),vimeo=u.hostname==="vimeo.com"||u.hostname.endsWith(".vimeo.com");let embed="";
 if(yt){let id=u.hostname==="youtu.be"?u.pathname.split("/").filter(Boolean)[0]:u.searchParams.get("v");if(!id){const parts=u.pathname.split("/").filter(Boolean);if(parts.length>1&&["embed","shorts","live"].includes(parts[0]))id=parts[1]}if(id&&/^[A-Za-z0-9_-]{6,20}$/.test(id)){const p=new URLSearchParams({rel:"0",playsinline:"1",controls:"1"});if(data.autoplay){p.set("autoplay","1");p.set("mute","1")}if(data.loop_video){p.set("loop","1");p.set("playlist",id)}embed="https://www.youtube-nocookie.com/embed/"+encodeURIComponent(id)+"?"+p.toString()}}
 else if(vimeo){const id=u.pathname.split("/").filter(Boolean).find(part=>/^\\d+$/.test(part));if(id){const p=new URLSearchParams({title:"0",byline:"0",portrait:"0",playsinline:"1"});if(data.autoplay){p.set("autoplay","1");p.set("muted","1")}if(data.loop_video)p.set("loop","1");embed="https://player.vimeo.com/video/"+id+"?"+p.toString()}}
 if(embed){const f=document.createElement("iframe");f.src=embed;f.title="Tacoma Community Hub featured video";f.allow="autoplay; fullscreen; picture-in-picture";f.allowFullscreen=true;f.loading="eager";layer.appendChild(f)}
 else{const v=document.createElement("video");v.src=u.href;v.controls=true;v.playsInline=true;v.preload="metadata";v.setAttribute("aria-label","Tacoma Community Hub featured video");if(data.poster_url){try{const p=new URL(data.poster_url);if(["https:","http:"].includes(p.protocol))v.poster=p.href}catch(e){}}if(data.autoplay){v.autoplay=true;v.muted=true;v.setAttribute("muted","")}if(data.loop_video)v.loop=true;v.addEventListener("error",()=>layer.remove(),{once:true});layer.appendChild(v);if(data.autoplay)v.play().catch(()=>{})}
 if(layer.childElementCount){const photo=$(".hero-photo",hero);if(photo)photo.classList.add("hero-photo-under-video");hero.insertBefore(layer,hero.querySelector(".hero-content"))}
 }catch(e){console.warn("Hero video could not load",e)}
}
