const content=section.querySelector("#admin-content");if(content){content.classList.add("admin-workspace");const bar=document.createElement("div");bar.className="admin-toolbar";bar.innerHTML='<div><span class="eyebrow">Moderation workspace</span><p>All actions remain subject to your assigned permissions and database security policies.</p><small id="admin-workspace-status" aria-live="polite">Waiting for authorization…</small></div><div class="admin-toolbar-actions"><button type="button" class="button" id="admin-refresh">↻ Refresh dashboard</button><button type="button" class="button" id="admin-export">↓ Export queue</button><button type="button" class="button" id="admin-export-reports">↓ Export reports</button></div>';content.prepend(bar);const q=content.querySelector("#admin-queue");if(q){const tools=document.createElement("div");tools.className="admin-queue-tools";tools.innerHTML='<label for="admin-queue-search">Filter pending submissions</label><input id="admin-queue-search" type="search" placeholder="Search title, type, summary or submitter…"><small id="admin-filter-count">Waiting for queue…</small>';q.before(tools)}}
const update=()=>{const pc=document.querySelector("#admin-pending-count"),rc=document.querySelector("#admin-report-count"),ac=document.querySelector("#admin-auth-state");const q=document.querySelector("#admin-queue"),r=document.querySelector("#admin-reports"),countRows=el=>el?el.querySelectorAll("tbody tr").length:0;if(pc&&q)pc.textContent=String(countRows(q));if(rc&&r)rc.textContent=String(countRows(r));const authorized=!!content&&!content.classList.contains("hidden");if(ac)ac.textContent=authorized?"Authorized":"Sign-in required";const ws=document.querySelector("#admin-workspace-status"),rt=document.querySelector("#admin-refresh-time");if(ws)ws.textContent=authorized?"Authorized session · "+countRows(q)+" pending · "+countRows(r)+" open reports":"Waiting for authorized session";if(rt)rt.textContent="Updated "+new Date().toLocaleTimeString([],{hour:"numeric",minute:"2-digit",second:"2-digit"})};
