/* Sitewide resilience, image loading and safer outbound-link defaults. */
(()=>{"use strict";document.addEventListener("DOMContentLoaded",()=>{
  document.querySelectorAll("img:not([fetchpriority=high])").forEach(img=>{if(!img.hasAttribute("loading"))img.loading="lazy";img.decoding="async"});
  document.querySelectorAll('a[target="_blank"]').forEach(link=>{const rel=new Set((link.getAttribute("rel")||"").split(/\s+/).filter(Boolean));rel.add("noopener");rel.add("noreferrer");link.setAttribute("rel",[...rel].join(" "))});
  let banner=document.querySelector("#hub-network-status");
  if(!banner){banner=document.createElement("div");banner.id="hub-network-status";banner.className="hub-network-status";banner.setAttribute("role","status");banner.setAttribute("aria-live","polite");banner.hidden=true;const header=document.querySelector(".site-header");if(header)header.insertAdjacentElement("afterend",banner)}
  const paint=()=>{if(!banner)return;banner.hidden=navigator.onLine;banner.textContent=navigator.onLine?"":"You are offline. Previously visited pages may be available; live chat, account actions and new submissions need a connection."};
  window.addEventListener("online",paint);window.addEventListener("offline",paint);paint();
});})();
